#include <cstddef>
#include <cstdint>
namespace { constexpr size_t C=4,R=4,MAXW=181; bool valid(const int64_t*b){for(size_t d=0;d<4;++d)if(b[d]<-8||b[d]>8||b[4+d]<-8||b[4+d]>8||b[d]>=b[4+d])return false;return true;} bool hit(const int64_t*b,const int64_t*q){for(size_t d=0;d<4;++d)if(q[d]>b[4+d]||b[d]>q[4+d])return false;return true;} void uni(const int64_t*x,size_t n,size_t s,int64_t*out){for(size_t d=0;d<4;++d){out[d]=x[d];out[4+d]=x[4+d];}for(size_t i=1;i<n;++i)for(size_t d=0;d<4;++d){if(x[i*s+d]<out[d])out[d]=x[i*s+d];if(x[i*s+4+d]>out[4+d])out[4+d]=x[i*s+4+d];}} void put(uint8_t*out,size_t w,int64_t x){uint64_t u=static_cast<uint64_t>(x);for(size_t b=0;b<8;++b)out[w*8+b]=static_cast<uint8_t>(u>>(8*b));} }
extern "C" int64_t versabench_dbms_delete_entry(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<10||n>190)return -1;int64_t cv=v[0];if(cv<1||cv>4)return -1;size_t nc=static_cast<size_t>(cv);int64_t q[8];for(size_t d=0;d<8;++d)q[d]=v[1+d];if(!valid(q))return -1;int64_t boxes[C][R][8]{},ids[C][R]{},mbr[C][8]{};size_t counts[C]{};bool seen[32]{};size_t p=9;
 for(size_t c=0;c<nc;++c){if(p+9>n)return -1;int64_t rv=v[p++];if(rv<1||rv>4||p+8+static_cast<size_t>(rv)*9>n)return -1;counts[c]=static_cast<size_t>(rv);for(size_t d=0;d<8;++d)mbr[c][d]=v[p++];if(!valid(mbr[c]))return -1;for(size_t r=0;r<counts[c];++r){for(size_t d=0;d<8;++d)boxes[c][r][d]=v[p++];ids[c][r]=v[p++];if(!valid(boxes[c][r])||ids[c][r]<0||ids[c][r]>=32||seen[ids[c][r]])return -1;seen[ids[c][r]]=true;}int64_t actual[8];uni(&boxes[c][0][0],counts[c],8,actual);for(size_t d=0;d<8;++d)if(actual[d]!=mbr[c][d])return -1;}
 if(p!=n)return -1;int64_t kept[C][R][8]{},kid[C][R]{},kmbr[C][8]{};size_t kc[C]{},remaining=0;for(size_t c=0;c<nc;++c){size_t k=0;for(size_t r=0;r<counts[c];++r){if(hit(mbr[c],q)&&hit(boxes[c][r],q))continue;for(size_t d=0;d<8;++d)kept[c][k][d]=boxes[c][r][d];kid[c][k++]=ids[c][r];}if(k){kc[remaining]=k;for(size_t r=0;r<k;++r){for(size_t d=0;d<8;++d)kept[remaining][r][d]=kept[c][r][d];kid[remaining][r]=kid[c][r];}uni(&kept[remaining][0][0],k,8,kmbr[remaining]);++remaining;}}
 int64_t words[MAXW];size_t w=0;words[w++]=static_cast<int64_t>(remaining);for(size_t c=0;c<remaining;++c){words[w++]=static_cast<int64_t>(kc[c]);for(size_t d=0;d<8;++d)words[w++]=kmbr[c][d];for(size_t r=0;r<kc[c];++r){for(size_t d=0;d<8;++d)words[w++]=kept[c][r][d];words[w++]=kid[c][r];}}size_t bytes=w*8;if(!out||cap<bytes)return -2;for(size_t i=0;i<w;++i)put(out,i,words[i]);return static_cast<int64_t>(bytes);}
